import { cn } from '@wildflowerhealthio/react-kitchen-sink'
import type { ComponentProps, JSX } from 'react'

import styles from './segmented-toggle.module.css'

/** One option in a {@link SegmentedToggle}. */
interface SegmentedToggleOption<T extends string> {
  readonly value: T
  readonly label: string
  /**
   * The option can't be picked now. Its button stays in the group, disabled;
   * say why somewhere the reader sees before reaching it.
   */
  readonly disabled?: boolean
}

/**
 * Props for {@link SegmentedToggle}: its value, options and `onChange`, and
 * any other `<div>` prop (`id`, `data-*`, `ref`, a `className` added to its
 * own), which go to the root group. Its `role` and children are its own, and
 * `onChange` is the picked value's, so a caller cannot set the `<div>`'s.
 */
interface SegmentedToggleProps<T extends string> extends Omit<
  ComponentProps<'div'>,
  'children' | 'role' | 'onChange' | 'aria-label'
> {
  readonly value: T
  readonly options: readonly SegmentedToggleOption<T>[]
  readonly onChange: (value: T) => void
  /** Accessible name announced for the group (e.g. "View"). */
  readonly 'aria-label': string
}

/**
 * A pill-shaped, one-of-N view toggle: a `role="group"` of `aria-pressed`
 * buttons, the pressed one painted in the accent. Native `<button>`s, so
 * Tab / Space work without any keyboard handler; `aria-pressed` (not
 * `aria-selected`) is the semantic — each button is an independent action
 * that latches on, not an option within a tablist.
 */
const SegmentedToggle = <T extends string>({
  value,
  options,
  onChange,
  'aria-label': ariaLabel,
  className,
  ...rootProps
}: SegmentedToggleProps<T>): JSX.Element => (
  <div {...rootProps} className={cn(styles['tabs'], className)} role="group" aria-label={ariaLabel}>
    {options.map((option) => (
      <button
        key={option.value}
        type="button"
        className={styles['tab']}
        aria-pressed={option.value === value}
        disabled={option.disabled === true}
        onClick={() => {
          onChange(option.value)
        }}
      >
        {option.label}
      </button>
    ))}
  </div>
)

export { SegmentedToggle, type SegmentedToggleOption, type SegmentedToggleProps }
